package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{now: t} }

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.now
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.now = f.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 1, 0, clk, true},
		{"negative rate", 1, -1, clk, true},
		{"valid", 5, 2.5, clk, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	cases := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"zero n always allowed", 2, 1, 0, 0, true},
		{"n exceeds capacity", 2, 1, 0, 3, false},
		{"full bucket allows capacity", 3, 1, 0, 3, true},
		{"empty bucket denies", 1, 1, 0, 1, true},
		{"refill after advance", 2, 2, 500 * time.Millisecond, 1, true},
		{"partial refill", 10, 10, 100 * time.Millisecond, 1, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock(base)
			b, err := New(tc.cap, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			if tc.advance > 0 {
				clk.Advance(tc.advance)
			}
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestAllowNConsumesAndRefills(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(2, 2, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(2) {
		t.Fatal("expected first AllowN(2)")
	}
	if b.AllowN(1) {
		t.Fatal("expected denial when empty")
	}
	clk.Advance(500 * time.Millisecond)
	if !b.AllowN(1) {
		t.Fatal("expected refill")
	}
	if b.AllowN(1) {
		t.Fatal("expected denial after refill consumed")
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(100, 1000, clk)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed %d, exceeds capacity", allowed)
	}
}
